<!doctype html><html><head><meta charset="utf-8"><title>Receipt</title><style>body{font-family:Arial,sans-serif;max-width:420px;margin:30px auto}.row{display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px dashed #ccc}</style></head><body><h2>Payment Receipt</h2><div class="row"><span>Reference</span><b>{{ $payment->reference }}</b></div><div class="row"><span>Method</span><b>{{ strtoupper($payment->method) }}</b></div><div class="row"><span>Amount</span><b>{{ number_format((float)$payment->amount,2) }} {{ $payment->currency }}</b></div><div class="row"><span>Status</span><b>{{ is_object($payment->status) ? $payment->status->value : $payment->status }}</b></div><p>Thank you.</p></body></html>
